import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        int h = in.nextInt();
        int maxQueue = 0;
        for (int i = 0; i < n; i++) {
            int q = in.nextInt();
            if (q > maxQueue) maxQueue = q;
        }
        System.out.println(maxQueue / h);
    }
}

